<div class="page-title clearfix"><h1>Monitor de Ponto · Sólides</h1></div>
<div class="card"><div class="card-body"><div class="d-flex justify-content-between align-items-center flex-wrap gap-2"><div><h4 class="mb-1">Central do Departamento Pessoal</h4><div class="text-muted">A Sólides continua sendo a fonte oficial. A Intranet apenas sincroniza, identifica possíveis pendências e alerta os funcionários.</div></div><button class="btn btn-primary" id="solides-sync"><i data-feather="refresh-cw" class="icon-16"></i> Sincronizar agora</button></div></div></div>
<div class="row mt-3"><div class="col-md-4"><div class="card"><div class="card-body"><div class="text-muted">Pendências encontradas</div><div class="fs-2 fw-bold"><?php echo count($alerts); ?></div></div></div></div><div class="col-md-4"><div class="card"><div class="card-body"><div class="text-muted">Marcações esperadas/dia</div><div class="fs-2 fw-bold"><?php echo (int)($settings['solides_expected_daily_punches'] ?? 4); ?></div></div></div></div><div class="col-md-4"><div class="card"><div class="card-body"><div class="text-muted">Última sincronização</div><div class="fw-bold"><?php echo esc($settings['solides_last_sync_at'] ?? 'Ainda não sincronizado'); ?></div></div></div></div></div>
<div class="card mt-3"><div class="card-header"><h4>Pendências para acompanhamento</h4></div><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Funcionário</th><th>Data</th><th>Marcações</th><th>Situação</th></tr></thead><tbody><?php if(!$alerts):?><tr><td colspan="4" class="text-center text-muted p-4">Nenhuma pendência sincronizada.</td></tr><?php endif;?><?php foreach($alerts as $a):?><tr><td><?php echo esc(trim($a->employee_name) ?: ('Sólides #'.$a->solides_employee_id));?></td><td><?php echo esc($a->work_date);?></td><td><strong><?php echo (int)$a->punch_count;?></strong> / <?php echo (int)$a->expected_count;?></td><td><span class="badge bg-warning text-dark">Conferir na Sólides</span></td></tr><?php endforeach;?></tbody></table></div></div>
<div class="card mt-3"><div class="card-header"><h4>Integração</h4></div><div class="card-body"><form id="solides-settings"><div class="row"><div class="col-md-6 mb-3"><label>URL base da API Sólides</label><input class="form-control" name="solides_api_base_url" value="<?php echo esc($settings['solides_api_base_url']??'');?>" placeholder="Informe a URL exibida no Swagger da sua conta"></div><div class="col-md-6 mb-3"><label>Endpoint de consulta de pontos</label><input class="form-control" name="solides_punches_endpoint" value="<?php echo esc($settings['solides_punches_endpoint']??'/');?>"></div><div class="col-md-6 mb-3"><label>Token de integração</label><input type="password" class="form-control" name="solides_api_token" value="<?php echo esc($settings['solides_api_token']??'');?>"></div><div class="col-md-3 mb-3"><label>Marcações esperadas</label><input type="number" min="1" class="form-control" name="solides_expected_daily_punches" value="<?php echo esc($settings['solides_expected_daily_punches']??'4');?>"></div><div class="col-md-6 mb-3"><label>Link para o funcionário abrir a Sólides</label><input class="form-control" name="solides_employee_portal_url" value="<?php echo esc($settings['solides_employee_portal_url']??'');?>"></div></div><button class="btn btn-primary" type="submit">Salvar integração</button></form></div></div>
<script>$(function(){if(window.feather)feather.replace();$('#solides-settings').on('submit',function(e){e.preventDefault();$.post('<?php echo get_uri('pontorh/solides/configuracoes');?>',$(this).serialize(),function(r){appAlert.success(r.message||'Salvo.');},'json');});$('#solides-sync').on('click',function(){var b=$(this);b.prop('disabled',true);$.post('<?php echo get_uri('pontorh/solides/sincronizar');?>',{},function(r){if(r.success){appAlert.success(r.message);setTimeout(function(){location.reload();},700);}else appAlert.error(r.message);},'json').always(function(){b.prop('disabled',false);});});});</script>
